ation changed through geological time.","alternatives":[{"id":"01a21904-ad54-7932-ac54-e95bda724603","description":"ancient multicelled plants","correct_answer":true},{"id":"01a21904-ad54-7895-a577-3d3ec4a9155c","description":"eggs","correct_answer":false},{"id":"01a21904-ad54-70b4-97f0-e7d8ed10d097","description":"the study, especially statistical, of elections","correct_answer":false},{"id":"01a21904-ad54-7cee-ab0d-26847a31cde0","description":"viruses","correct_answer":false}]},{"id":"01a21904-ad54-708e-b28f-2c1a7ddfa999","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is the other name for the Celsius temperature scale, meaning \"divided into one hundred parts\"?","difficulty":2,"explanation":"Centigrade refers to the 100-degree interval between water\u2019s freezing and boiling points at standard atmospheric pressure.","alternatives":[{"id":"01a21904-ad54-7e75-b831-fcf8f2bc971d","description":"Centigrade","correct_answer":true},{"id":"01a21904-ad54-74b6-a8cf-cf4709358242","description":"Fahrenheit","correct_answer":false},{"id":"01a21904-ad54-7c22-ad7d-7875bea2eb85","description":"Kelvin","correct_answer":false},{"id":"01a21904-ad54-7465-9076-385efb133b60","description":"Rankine","correct_answer":false}]},{"id":"01a21904-ad54-7358-ac07-4fe8f49c6a8c","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What adjective is attached to both Gustave Pasch\'s match and Walter Hunt\'s pin?","difficulty":2,"explanation":"Safety matches keep key chemicals apart until striking, while a safety pin\'s clasp covers its sharp point.","alternatives":[{"id":"01a21904-ad54-7eb0-a8ae-94ae62f4332f","description":"Safety","correct_answer":true},{"id":"01a21904-ad54-7c5c-93d6-8ae78642a9de","description":"Sharp","correct_answer":false},{"id":"01a21904-ad54-7739-85a5-78fe0f86bd15","description":"Smooth","correct_answer":false},{"id":"01a21904-ad54-7877-b09f-44ee0ac8b842","description":"Bright","correct_answer":false}]},{"id":"01a21904-ad54-75e3-a3c9-12d8c219