ion.","alternatives":[{"id":"01a21904-ad54-7042-a5c0-785e6e7775c5","description":"Refraction","correct_answer":true},{"id":"01a21904-ad54-798e-9777-46e96df164ea","description":"Reflection","correct_answer":false},{"id":"01a21904-ad54-7daa-8a4c-add25d8db68b","description":"Convection","correct_answer":false},{"id":"01a21904-ad54-716e-962c-4fde7341407d","description":"Ablation","correct_answer":false}]},{"id":"01a21904-ad54-70b5-bbfb-6000f12f8690","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"Which substance takes its name from the Greek for `not flammable\'?","difficulty":2,"explanation":"Asbestos fibers were used in insulation and other heat-resistant materials, but inhaling them can cause serious disease.","alternatives":[{"id":"01a21904-ad54-72ee-b2ed-26124c0e9450","description":"Asbestos","correct_answer":true},{"id":"01a21904-ad54-7262-b488-97b6dc2353a4","description":"Bleach","correct_answer":false},{"id":"01a21904-ad54-78bd-8fbf-4ac2872ca295","description":"Ethanol","correct_answer":false},{"id":"01a21904-ad54-7fe7-966d-1d7c12b8a6b9","description":"Methadone","correct_answer":false}]},{"id":"01a21904-ad54-7ccd-a0ef-c58402586dd8","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"In mammals, which organ produces milk?","difficulty":2,"explanation":"Mammary glands are modified sweat glands, and prolactin helps stimulate milk production after birth.","alternatives":[{"id":"01a21904-ad54-73e0-90e9-cba062d72eee","description":"Mammary gland","correct_answer":true},{"id":"01a21904-ad54-7a04-a78f-55516818b178","description":"Prostate","correct_answer":false},{"id":"01a21904-ad54-7078-aad3-51ddaeedd76f","description":"Pancreas","correct_answer":false},{"id":"01a21904-ad54-7817-b72c-94ef01b316c9","description":"Pituitary gland","correct_answer":false}]},{"id":"01a21904-ad54-7072-af18-eecec187ce4b","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"Which organisms use gills for breathing?","difficulty":2,"explanation":"Many aquatic 